-- Remove only unused addon records whose owner no longer exists.
DELETE a FROM creature_addon a LEFT JOIN creature c ON c.guid=a.guid WHERE a.guid IN (564238,564239,564240) AND c.guid IS NULL;
-- These stationary caster spawns have no waypoint data or SmartAI path-start actions.
UPDATE creature_addon a JOIN creature c ON c.guid=a.guid SET a.path_id=0 WHERE a.guid IN (914942,522984) AND c.MovementType=0 AND NOT EXISTS (SELECT 1 FROM waypoint_data w WHERE w.id=a.path_id);

-- Original LoA reference assigns these NPCs to existing SmartAI; the named native scripts do not exist in this build.
UPDATE creature_template SET AIName='SmartAI',ScriptName='' WHERE entry=35077 AND ScriptName='npc_lord_darius_crowley_c1' AND AIName='';
